// Compile-Time Polymorphism (Template Instantiation)

template <typename T>
T max_val(T a, T b) { return (a > b) ? a : b; }

// Compiler performs Monomorphization (Code Generation):
// 1. Instantiates max_val<int>
int i = max_val(10, 20);

// 2. Instantiates max_val<double>
double d = max_val(10.5, 9.5);

// The compiler generates two distinct, optimized functions
// chosen entirely at compile time (Static Dispatch).
// Zero runtime lookup overhead (unlike VTables).
